fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    if strings.is_empty() {
        return None;
    }

    let mut max_len = 0;
    let mut max_index = 0;

    for (i, s) in strings.iter().enumerate() {
        if s.len() > max_len {
            max_len = s.len();
            max_index = i;
        }
    }

    // Since max_index points to the earliest max length sequence,
    // clone and return it inside Some
    Some(strings[max_index].clone())
}